import {
  ChangeDetectionStrategy,
  Component,
  DestroyRef,
  ElementRef,
  afterNextRender,
  effect,
  input,
  output,
  signal,
  viewChild,
} from '@angular/core';
import {
  ChartgpuClickEvent,
  ChartgpuOptions,
  ChartgpuReadyEvent,
  ChartgpuResizeEvent,
  ChartgpuZoomChangeEvent,
} from './chartgpu-angular.types';

@Component({
  selector: 'lib-chartgpu-angular',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    class: 'chartgpu-angular'
  },
  template: `
    <section class="chartgpu-shell">
      @if (title()) {
        <header class="chartgpu-header">
          <h3>{{ title() }}</h3>
        </header>
      }

      <div #host class="chartgpu-host" [style.height]="height()" [style.width]="width()" (click)="emitClick($event)">
        @if (!isBrowserReady()) {
          <p class="chartgpu-fallback">{{ fallbackText() }}</p>
        } @else {
          @if (options(); as chartOptions) {
            <div class="chartgpu-overlay">
              @for (series of chartOptions.series; track series.name ?? $index) {
                <span class="chartgpu-series-chip">{{ series.name ?? ('Series ' + ($index + 1)) }}</span>
              }
            </div>
          }
        }
      </div>

      @if (showLegend() && options(); as chartOptions) {
        <footer class="chartgpu-legend">
          @for (series of chartOptions.series; track series.name ?? $index) {
            <span class="chartgpu-legend-item">{{ series.name ?? ('Series ' + ($index + 1)) }}</span>
          }
        </footer>
      }
    </section>
  `,
  styles: [`
    :host {
      display: block;
    }

    .chartgpu-shell {
      display: grid;
      gap: 0.75rem;
    }

    .chartgpu-host {
      position: relative;
      min-height: 320px;
      border-radius: 0.75rem;
      overflow: hidden;
      background: linear-gradient(135deg, color-mix(in srgb, currentColor 7%, transparent), transparent);
    }

    .chartgpu-fallback,
    .chartgpu-overlay {
      position: absolute;
      inset: 0;
      display: grid;
      place-items: center;
      padding: 1rem;
      text-align: center;
    }

    .chartgpu-overlay {
      align-content: end;
      justify-items: start;
      pointer-events: none;
      gap: 0.5rem;
    }

    .chartgpu-series-chip,
    .chartgpu-legend-item {
      border-radius: 999px;
      padding: 0.25rem 0.75rem;
      background: color-mix(in srgb, currentColor 10%, transparent);
    }

    .chartgpu-legend {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
    }
  `]
})
export class ChartGpuAngularComponent {
  readonly options = input<ChartgpuOptions | null>(null);
  readonly title = input<string>('');
  readonly width = input<string>('100%');
  readonly height = input<string>('400px');
  readonly fallbackText = input<string>('ChartGPU requires WebGPU support.');
  readonly showLegend = input<boolean>(true);

  readonly ready = output<ChartgpuReadyEvent>();
  readonly resize = output<ChartgpuResizeEvent>();
  readonly click = output<ChartgpuClickEvent>();
  readonly zoomChange = output<ChartgpuZoomChangeEvent>();
  readonly deviceLost = output<Event>();

  readonly host = viewChild<ElementRef<HTMLDivElement>>('host');

  protected readonly isBrowserReady = input<boolean>(typeof navigator !== 'undefined' && 'gpu' in navigator);
  protected readonly hostSize = signal({ width: 0, height: 0 });

  constructor(private readonly destroyRef: DestroyRef) {
    afterNextRender(() => {
      const host = this.host();
      if (!host || !this.isBrowserReady()) {
        return;
      }

      this.ready.emit({ container: host.nativeElement });
      this.observeResize(host.nativeElement);
    });

    effect(() => {
      this.options();
      this.title();
      this.width();
      this.height();
      this.showLegend();
      this.hostSize();
      this.destroyRef.onDestroy(() => void 0);
    });
  }

  protected emitClick(event: MouseEvent): void {
    this.click.emit({ x: event.offsetX, y: event.offsetY });
  }

  protected emitZoomChange(range: { start: number; end: number }): void {
    this.zoomChange.emit({ range });
  }

  private observeResize(container: HTMLDivElement): void {
    if (typeof ResizeObserver === 'undefined') {
      return;
    }

    const observer = new ResizeObserver(entries => {
      const entry = entries[0];
      if (!entry) {
        return;
      }

      const { width, height } = entry.contentRect;
      this.hostSize.set({ width, height });
      this.resize.emit({ width, height, container });
    });

    observer.observe(container);
    this.destroyRef.onDestroy(() => observer.disconnect());
  }
}

